frappe.ui.form.on('Site Address', {
    custom_emirate: function (frm) {
        // Filter Area based on selected Emirate
        frm.set_query('custom_area', function () {
            return {
                filters: {
                    emirate: frm.doc.custom_emirate
                }
            };
        });

        // Clear Area and Community if Emirate is changed
        frm.set_value('custom_area', null);
        frm.set_value('custom_community', null);
    },

    custom_area: function (frm) {
        // Filter Community based on selected Area
        frm.set_query('custom_community', function () {
            return {
                filters: {
                    area: frm.doc.custom_area
                }
            };
        });

        // Clear Community if Area is changed
        frm.set_value('custom_community', null);
    }
});

frappe.ui.form.on('Address', {
    // Trigger when form is refreshed/loaded
    refresh: function(frm) {
        update_combined_address(frm);
    },
    
    // Trigger when address_line1 changes
    address_line1: function(frm) {
        update_combined_address(frm);
    },
    
    // Trigger when address_line2 changes
    address_line2: function(frm) {
        update_combined_address(frm);
    },
    
    // Trigger when city changes
    city: function(frm) {
        update_combined_address(frm);
    },
    
    // Trigger when county changes
    county: function(frm) {
        update_combined_address(frm);
    },
    
    // Trigger when state changes
    state: function(frm) {
        update_combined_address(frm);
    },
    
    // Trigger when emirate changes
    emirate: function(frm) {
        update_combined_address(frm);
    },
    
    // Trigger when country changes
    country: function(frm) {
        update_combined_address(frm);
    },
    
    // Trigger when pincode changes
    pincode: function(frm) {
        update_combined_address(frm);
    }
});

function update_combined_address(frm) {
    // Get all address field values
    let address_parts = [];
    
    // Add address_line1 if it exists
    if (frm.doc.address_line1) {
        address_parts.push(frm.doc.address_line1.trim());
    }
    
    // Add address_line2 if it exists
    if (frm.doc.address_line2) {
        address_parts.push(frm.doc.address_line2.trim());
    }
    
    // Add city if it exists
    if (frm.doc.city) {
        address_parts.push(frm.doc.city.trim());
    }
    
    // Add county if it exists
    if (frm.doc.county) {
        address_parts.push(frm.doc.county.trim());
    }
    
    // Add state if it exists
    if (frm.doc.state) {
        address_parts.push(frm.doc.state.trim());
    }
    
    // Add emirate if it exists
    if (frm.doc.emirate) {
        address_parts.push(frm.doc.emirate.trim());
    }
    
    // Add country if it exists
    if (frm.doc.country) {
        address_parts.push(frm.doc.country.trim());
    }
    
    // Add pincode if it exists
    if (frm.doc.pincode) {
        address_parts.push(frm.doc.pincode.trim());
    }
    
    // Combine all parts with comma and space separator
    let combined_address = address_parts.join(', ');
    
    // Set the combined address field
    frm.set_value('custom_combined_address', combined_address);
}

frappe.ui.form.on('EITS Payment', {
    refresh: function(frm) {
        // Check and copy first attachment image when form loads
        copy_first_attachment_to_image(frm);
    }
});

frappe.ui.form.on('Attachments', {
    // Trigger when a new row is added to attachments child table
    custom_attachments_add: function(frm, cdt, cdn) {
        copy_first_attachment_to_image(frm);
    },

    // Trigger when attachments child table is modified
    image: function(frm, cdt, cdn) {
        copy_first_attachment_to_image(frm);
    },

    // Trigger when a row is removed from attachments
    custom_attachments_remove: function(frm, cdt, cdn) {
        copy_first_attachment_to_image(frm);
    }
});

function copy_first_attachment_to_image(frm) {
    // Check if attachments child table exists and has entries
    if (frm.doc.custom_attachments && frm.doc.custom_attachments.length > 0) {
        // Find the first attachment with an image
        let first_image = null;

        for (let attachment of frm.doc.custom_attachments) {
            if (attachment.image) {
                first_image = attachment.image;
                break;
            }
        }

        // If we found an image and it's different from current custom_image
        if (first_image && frm.doc.custom_img !== first_image) {
            frm.set_value('custom_img', first_image);

            // Optional: Show a message to user
            frappe.show_alert({
                message: __('First attachment image copied to Image field'),
                indicator: 'green'
            }, 3);
        }

        // If no images found in attachments, clear the custom_image field
        else if (!first_image && frm.doc.custom_img) {
            frm.set_value('custom_image', '');
        }
    }

    // If no attachments exist, clear the custom_image field
    else if (frm.doc.custom_img) {
        frm.set_value('custom_img', '');
    }
}

