// Function to calculate amount for Pressing Charges
function calculate_pressing_amount(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    
    if (row.no_of_sides && row.price) {
        let amount = flt(row.no_of_sides) * flt(row.price);
        frappe.model.set_value(cdt, cdn, 'amount', amount);
        frm.refresh_field('custom_pressing_charges'); // Replace with your actual field name
    }
}

// Function to calculate amount for Material Sold
function calculate_material_amount(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    
    if (row.no_of_sides && row.price) {
        let amount = flt(row.no_of_sides) * flt(row.price);
        frappe.model.set_value(cdt, cdn, 'amount', amount);
        frm.refresh_field('custom_material_sold'); // Replace with your actual field name
    }
}

