frappe.ui.form.on('Work', {
   expected_start_date: function (frm, cdt, cdn) {
       if (!validate_time_overlap(frm, cdt, cdn)) return;
       calculate_end_time(frm, cdt, cdn);
   },
   expected_time_in_hours: function (frm, cdt, cdn) {
       calculate_end_time(frm, cdt, cdn);
       // Validate overlap after calculating new end time
       validate_time_overlap(frm, cdt, cdn);
   }
});

function calculate_end_time(frm, cdt, cdn) {
   let row = locals[cdt][cdn];
   
   if (row.expected_start_date && row.expected_time_in_hours && frm.doc.date) {
       // Combine parent date and start time
       const datetime_str = frm.doc.date + ' ' + row.expected_start_date;
       
       let start = moment(datetime_str, ['YYYY-MM-DD HH:mm:ss', 'DD-MM-YYYY HH:mm:ss']);
       if (start.isValid()) {
           let end = start.clone().add(row.expected_time_in_hours, 'hours');
           
           // Only save time part in end_time
           frappe.model.set_value(cdt, cdn, 'end_time', end.format('HH:mm:ss'));
       } else {
           frappe.msgprint("Start time or date invalid");
       }
   }
}

function validate_time_overlap(frm, cdt, cdn) {
   let current = locals[cdt][cdn];
   
   if (!current.expected_start_date || !current.expected_time_in_hours || !frm.doc.date) return true;
   
   const current_start = moment(frm.doc.date + ' ' + current.expected_start_date, ['YYYY-MM-DD HH:mm:ss', 'DD-MM-YYYY HH:mm:ss']);
   if (!current_start.isValid()) return true;
   
   // Calculate current task's end time
   const current_end = current_start.clone().add(current.expected_time_in_hours, 'hours');
   
   const child_rows = frm.doc.custom_work_allocation || [];
   
   for (let row of child_rows) {
       if (row.name === current.name) continue;
       
       if (row.expected_start_date && row.expected_time_in_hours) {
           const row_start = moment(frm.doc.date + ' ' + row.expected_start_date, ['YYYY-MM-DD HH:mm:ss', 'DD-MM-YYYY HH:mm:ss']);
           const row_end = row_start.clone().add(row.expected_time_in_hours, 'hours');
           
           if (row_start.isValid() && row_end.isValid()) {
               // Check all 5 overlap cases
               let isOverlapping = false;
               let overlapType = '';
               
               // Case 1: Complete Overlap (New inside Existing)
               // existing_start <= new_start AND new_end <= existing_end
               if (row_start.isSameOrBefore(current_start) && current_end.isSameOrBefore(row_end)) {
                   isOverlapping = true;
                   overlapType = 'completely inside';
               }
               // Case 2: Starts Before and Ends Inside
               // new_start < existing_start AND new_end > existing_start AND new_end <= existing_end
               else if (current_start.isBefore(row_start) && current_end.isAfter(row_start) && current_end.isSameOrBefore(row_end)) {
                   isOverlapping = true;
                   overlapType = 'starts before and ends inside';
               }
               // Case 3: Starts Inside and Ends After
               // new_start >= existing_start AND new_start < existing_end AND new_end > existing_end
               else if (current_start.isSameOrAfter(row_start) && current_start.isBefore(row_end) && current_end.isAfter(row_end)) {
                   isOverlapping = true;
                   overlapType = 'starts inside and ends after';
               }
               // Case 4: Exact Match
               // new_start === existing_start AND new_end === existing_end
               else if (current_start.isSame(row_start) && current_end.isSame(row_end)) {
                   isOverlapping = true;
                   overlapType = 'exactly matches';
               }
               // Case 5: Fully Overlapping Existing
               // new_start < existing_start AND new_end > existing_end
               else if (current_start.isBefore(row_start) && current_end.isAfter(row_end)) {
                   isOverlapping = true;
                   overlapType = 'completely wraps around';
               }
               
               if (isOverlapping) {
                   frappe.msgprint(`Task time (${current.expected_start_date} - ${current_end.format('HH:mm:ss')}) ${overlapType} existing task "${row.work_title || 'Untitled'}" (${row.expected_start_date} - ${row_end.format('HH:mm:ss')})`);
                   frappe.model.set_value(cdt, cdn, 'expected_start_date', null);
                   frappe.model.set_value(cdt, cdn, 'end_time', null);
                   return false;
               }
           }
       }
   }
   
   return true;
}

frappe.ui.form.on('Payment', {
    refresh: function(frm) {
        setup_attachment_preview(frm);

        // Listen for file uploads after input is ready
        setTimeout(function() {
            if (frm.fields_dict.attachments && frm.fields_dict.attachments.$input) {
                frm.fields_dict.attachments.$input.on('change', function() {
                    setTimeout(function() {
                        setup_attachment_preview(frm);
                    }, 700);
                });
            }
        }, 500);
    },

    after_save: function(frm) {
        setup_attachment_preview(frm);
    },

    attachments: function(frm) {
        setup_attachment_preview(frm);
    }
});

function setup_attachment_preview(frm) {
    // Defensive: Check if the HTML field exists
    if (!frm.fields_dict.attachment_preview) return;

    frm.fields_dict.attachment_preview.$wrapper.empty();

    const file_url = frm.doc.attachments;

    if (file_url) {
        // Image preview if image, otherwise link
        if (is_image_file(file_url)) {
            let html = `
            <div style="text-align:center; padding:15px;">
                <strong>Image Preview</strong>
                <div style="margin:10px auto; border:2px dashed #ccc; border-radius:7px; max-width:350px; padding:8px;">
                    <img src="${file_url}"
                         style="max-width:100%; max-height:250px; border:1px solid #ddd; border-radius:4px; cursor:pointer;"
                         onclick="window.open('${file_url}', '_blank')"
                         title="Click to open in new tab"
                    >
                </div>
                <div style="color:#888; font-size:12px;">Click to open full image</div>
            </div>
            `;
            frm.fields_dict.attachment_preview.$wrapper.html(html);
        } else {
            let file_name = file_url.split('/').pop();
            let html = `
            <div style="text-align:center; padding:15px;">
                <strong>File Attached</strong>
                <div style="margin:12px auto; border:2px dashed #ccc; border-radius:7px; max-width:350px; padding:18px;">
                    <i class="fa fa-file fa-3x" style="margin-bottom:8px; color:#666;"></i><br>
                    <div style="word-break:break-all; font-weight:bold; margin:8px auto;">${file_name}</div>
                    <a href="${file_url}" target="_blank" class="btn btn-primary btn-xs">
                        <i class="fa fa-external-link"></i> Open File
                    </a>
                </div>
            </div>
            `;
            frm.fields_dict.attachment_preview.$wrapper.html(html);
        }
    } else {
        // No file selected yet
        let placeholder = `
        <div style="text-align:center; padding:25px;">
            <div style="border:2px dashed #ddd; border-radius:8px; color:#aaa; padding:30px;">
                <i class="fa fa-upload fa-2x" style="margin-bottom:14px;"></i>
                <div>No attachment uploaded yet</div>
                <div style="font-size:11px; margin-top:2px;">Upload a file to see its preview here</div>
            </div>
        </div>
        `;
        frm.fields_dict.attachment_preview.$wrapper.html(placeholder);
    }
}

// Utility: Detect image type
function is_image_file(url) {
    const img_exts = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp', '.svg'];
    return img_exts.some(ext => url && url.toLowerCase().includes(ext));
}

