frappe.ui.form.on('Job Tracker', {
    status: function (frm) {
        // Hide all conditional fields by default
        frm.set_df_property('reason', 'hidden', 1);
        frm.set_df_property('percentage_of_work_done', 'hidden', 1);

        // Show fields based on status value
        if (frm.doc.status === 'Not started') {
            frm.set_df_property('reason', 'hidden', 0);
        } else if (frm.doc.status === 'Active' || frm.doc.status === 'Work in progress') {
