            update_image_preview(frm);
        }, 100);
    },
    
    custom_attachments_add: function(frm, cdt, cdn) {
        // Update preview when new row is added
        update_image_preview(frm);
    }
});

function update_image_preview(frm) {
    // Get the container element
    const container = document.getElementById('all-images-container');
    
    if (!container) {
        console.log('Container not found');
        return;
    }
    
    // Clear existing content
    container.innerHTML = '';
    
    // Get all attachment rows
    const attachments = frm.doc.custom_attachments || [];
    
    if (attachments.length === 0) {
        container.innerHTML = '<p style="text-align: center; color: #888; padding: 20px;">No images attached</p>';
        return;
    }
    
    // Create a grid container for images
    const gridContainer = document.createElement('div');
    gridContainer.style.cssText = `
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
        gap: 15px;
        padding: 10px;
    `;
    
    attachments.forEach((attachment, index) => {
        if (attachment.image) {
            // Create image container
            const imageContainer = document.createElement('div');
            imageContainer.style.cssText = `
                border: 1px solid #ddd;
                border-radius: 8px;
                padding: 10px;
                background: #f9f9f9;
                text-align: center;
            `;
            
            // Create image element
            const img = document.createElement('img');
            img.src = attachment.image;
            img.alt = attachment.remarks || `Image ${index + 1}`;
            img.style.cssText = `
                max-width: 100%;
                height: 200px;
                object-fit: cover;
                border-radius: 4px;
                cursor: pointer;
                transition: transform 0.2s;
            `;
            
            // Add hover effect
            img.onmouseover = function() {
                this.style.transform = 'scale(1.05)';
            };
            img.onmouseout = function() {
                this.style.transform = 'scale(1)';
            };
            
            // Add click to view full size
            img.onclick = function() {
                window.open(attachment.image, '_blank');
            };
            
            // Create remarks/caption
            const caption = document.createElement('div');
            caption.style.cssText = `
                margin-top: 8px;
                font-size: 12px;
                color: #666;
                word-wrap: break-word;
            `;
            caption.textContent = attachment.remarks || `Image ${index + 1}`;
            
            // Add elements to container
            imageContainer.appendChild(img);
            imageContainer.appendChild(caption);
            gridContainer.appendChild(imageContainer);
        }
    });
    
    // Add the grid to main container
    container.appendChild(gridContainer);
}

frappe.ui.form.on('Site Address', {
    refresh: function(frm) {
        set_combined_address(frm);
    },

    custom_emirate: function(frm) {
        set_combined_address(frm);
    },

    custom_area: function(frm) {
        set_combined_address(frm);
    },

    custom_community: function(frm) {
        set_combined_address(frm);
    },

    custom_street_name: function(frm) {
        set_combined_address(frm);
    },

    custom_property_number: function(frm) {
        set_combined_address(frm);
    },
    custom_property_category: function(frm) {
        set_combined_address(frm);
    },
    custom_property_type: function(frm) {
        set_combined_address(frm);
    }
});

function set_combined_address(frm) {
    const emirate = frm.doc.custom_emirate || '';
    const area = frm.doc.custom_area || '';
    const community = frm.doc.custom_community || '';
    const street = frm.doc.custom_street_name || '';
    const prop = frm.doc.custom_property_number || '';
    const cat = frm.doc.custom_property_category || '';
    const type = frm.doc.custom_property_type || '';



    // Join non-empty parts with commas
    const parts = [emirate, area, community, street, prop,cat,type].filter(Boolean);
    const combined = parts.join(', ');

    frm.set_value('custom_combined_address', combined);
}

frappe.ui.form.on('Lead', {
