        // Filter Community based on selected Area
        frm.set_query('custom_community', function () {
            return {
                filters: {
                    area: frm.doc.custom_area
                }
            };
        });

        // Clear Community if Area is changed
        frm.set_value('custom_community', null);
    }
});

