frappe.ui.form.on('Work', {
    expected_start_date: function (frm, cdt, cdn) {
        validate_start_and_end_time(cdt, cdn, "expected_start_date");
    },
    end_time: function (frm, cdt, cdn) {
        validate_start_and_end_time(cdt, cdn, "end_time");
    }
});

function validate_start_and_end_time(cdt, cdn, fieldname) {
    let row = locals[cdt][cdn];
   

    let time = moment(row[fieldname], "HH:mm:ss");
    let startLimit = moment("08:00:00", "HH:mm:ss");
    let endLimit   = moment("18:00:00", "HH:mm:ss");

    if (time.isBefore(startLimit) || time.isAfter(endLimit)) {
        frappe.msgprint({
            title: __("Invalid Time"),
            message: __("Start Time and End time must be between 8:00 AM and 6:00 PM"),
            indicator: "red"
        });
        row[fieldname] = null; // reset invalid value
        refresh_field(fieldname, row.name, row.parentfield);
    }
}
